-- Restore previous builtin definitions without changing enabled state.
UPDATE trace_detection_rules SET name = 'Downgrade pg_isready shadow read', description = 'pg_isready reads /etc/shadow during health checks. This is a known PostgreSQL behavior and not malicious.', action = 'downgrade', conditions = '[{"field":"comm","op":"eq","value":"pg_isready"},{"field":"filename","op":"contains","value":"/etc/shadow"}]'::jsonb, severity_override = 0, tags = ARRAY(SELECT jsonb_array_elements_text('["postgresql","false-positive"]'::jsonb)), updated_at = NOW() WHERE built_in = true AND name = 'Tag pg_isready shadow access';
UPDATE trace_detection_rules SET name = 'Downgrade pg_isready passwd read', description = 'pg_isready reads /etc/passwd during health checks. Expected behavior.', action = 'downgrade', conditions = '[{"field":"comm","op":"eq","value":"pg_isready"},{"field":"filename","op":"contains","value":"/etc/passwd"}]'::jsonb, severity_override = 0, tags = ARRAY(SELECT jsonb_array_elements_text('["postgresql","false-positive"]'::jsonb)), updated_at = NOW() WHERE built_in = true AND name = 'Downgrade pg_isready passwd read';
UPDATE trace_detection_rules SET name = 'Suppress logrotate log access', description = 'logrotate accessing /var/log is its intended purpose.', action = 'suppress', conditions = '[{"field":"comm","op":"eq","value":"logrotate"},{"field":"filename","op":"contains","value":"/var/log"}]'::jsonb, severity_override = NULL, tags = ARRAY(SELECT jsonb_array_elements_text('["logrotate","false-positive"]'::jsonb)), updated_at = NOW() WHERE built_in = true AND name = 'Suppress logrotate log access';
UPDATE trace_detection_rules SET name = 'Suppress local health-check curl', description = 'curl connecting to 127.0.0.1 or localhost is typically a health check probe.', action = 'suppress', conditions = '[{"field":"comm","op":"eq","value":"curl"},{"field":"addr","op":"contains","value":"127.0.0.1"}]'::jsonb, severity_override = NULL, tags = ARRAY(SELECT jsonb_array_elements_text('["health-check","false-positive"]'::jsonb)), updated_at = NOW() WHERE built_in = true AND name = 'Suppress local health-check curl';
UPDATE trace_detection_rules SET name = 'Escalate unknown binary setuid', description = 'setuid called by an unknown process (not sshd/su/sudo/login/runc) is highly suspicious.', action = 'escalate', conditions = '[{"field":"event_name","op":"eq","value":"setuid"},{"field":"comm","op":"not_in","value":["sshd","sshd-session","sshd-auth","su","sudo","login","passwd","newgrp","runuser","su-l","runc","runc:[2:INIT]","containerd-shim","containerd","dockerd","kubelet","cron","crond","at","systemd","nginx","mysqld","mariadbd","postgres","redis-server","dovecot","haproxy","varnishd","openvpn","memcached","zabbix_agentd","unattended-upgr","apt.systemd.dai","ansible","osqueryi"]}]'::jsonb, severity_override = 4, tags = ARRAY(SELECT jsonb_array_elements_text('["privilege-escalation","high-signal"]'::jsonb)), updated_at = NOW() WHERE built_in = true AND name = 'Tag unknown binary root UID request';
UPDATE trace_detection_rules SET name = 'Escalate /etc/shadow read by unknown process', description = 'Reading /etc/shadow outside of known auth processes is a strong indicator of credential harvesting.', action = 'escalate', conditions = '[{"field":"filename","op":"contains","value":"/etc/shadow"},{"field":"comm","op":"not_in","value":["sshd","sshd-session","sshd-auth","login","passwd","chage","useradd","usermod","pg_isready","postgres","shadow","unix_chkpwd","ansible","chef-client","puppet","osqueryi","aide","tripwire","restic","borg","bacula-fd","urbackupclient","backuppc"]}]'::jsonb, severity_override = 4, tags = ARRAY(SELECT jsonb_array_elements_text('["credential-access","high-signal"]'::jsonb)), updated_at = NOW() WHERE built_in = true AND name = 'Escalate /etc/shadow read by unknown process';
UPDATE trace_detection_rules SET name = 'Tag crontab modification', description = 'Writing to /var/spool/cron may indicate persistence via cron backdoor.', action = 'tag', conditions = '[{"field":"filename","op":"contains","value":"/var/spool/cron"},{"field":"event_name","op":"eq","value":"openat"},{"field":"flags","op":"bit_and","value":1}]'::jsonb, severity_override = NULL, tags = ARRAY(SELECT jsonb_array_elements_text('["persistence","cron"]'::jsonb)), updated_at = NOW() WHERE built_in = true AND name = 'Tag crontab modification';
UPDATE trace_detection_rules SET name = 'Downgrade auth daemon PAM config reads', description = 'sshd, login, su, sudo and other auth daemons routinely read /etc/pam.d/* as part of the normal authentication flow. Not an attack.', action = 'downgrade', conditions = '[{"field":"event_name","op":"eq","value":"openat"},{"field":"comm","op":"in","value":["sshd","login","su","sudo","unix_chkpwd","passwd","systemd-logind","gdm","gdm3","lightdm","polkitd","dbus-daemon","pam_unix","nologin"]},{"field":"filename","op":"contains","value":"/etc/pam"}]'::jsonb, severity_override = 0, tags = ARRAY(SELECT jsonb_array_elements_text('["auth","false-positive"]'::jsonb)), updated_at = NOW() WHERE built_in = true AND name = 'Downgrade auth daemon PAM config reads';
UPDATE trace_detection_rules SET name = 'Downgrade auth daemon security config reads', description = 'Auth daemons reading /etc/security/* (limits, access, etc.) is part of PAM stack execution — expected behavior.', action = 'downgrade', conditions = '[{"field":"event_name","op":"eq","value":"openat"},{"field":"comm","op":"in","value":["sshd","login","su","sudo","unix_chkpwd","passwd","systemd-logind","polkitd"]},{"field":"filename","op":"contains","value":"/etc/security"}]'::jsonb, severity_override = 0, tags = ARRAY(SELECT jsonb_array_elements_text('["auth","false-positive"]'::jsonb)), updated_at = NOW() WHERE built_in = true AND name = 'Downgrade auth daemon security config reads';
UPDATE trace_detection_rules SET name = 'Downgrade sshd SSH config reads', description = 'sshd reads /etc/ssh/sshd_config and host key files on startup and during connection. Expected operation.', action = 'downgrade', conditions = '[{"field":"event_name","op":"eq","value":"openat"},{"field":"comm","op":"eq","value":"sshd"},{"field":"filename","op":"starts_with","value":"/etc/ssh/"}]'::jsonb, severity_override = 1, tags = ARRAY(SELECT jsonb_array_elements_text('["ssh","false-positive"]'::jsonb)), updated_at = NOW() WHERE built_in = true AND name = 'Downgrade sshd SSH config reads';
UPDATE trace_detection_rules SET name = 'Downgrade init system /etc reads', description = 'systemd and init read most of /etc/ during boot and service management. These are expected reads.', action = 'downgrade', conditions = '[{"field":"event_name","op":"eq","value":"openat"},{"field":"comm","op":"in","value":["systemd","init","systemd-udevd"]},{"field":"filename","op":"starts_with","value":"/etc/"}]'::jsonb, severity_override = 1, tags = ARRAY(SELECT jsonb_array_elements_text('["init","false-positive"]'::jsonb)), updated_at = NOW() WHERE built_in = true AND name = 'Downgrade init system /etc reads';
UPDATE trace_detection_rules SET name = 'Downgrade package manager /etc reads', description = 'Package managers (apt, dpkg, yum, dnf) read /etc/ to check installed configs. Expected during updates.', action = 'downgrade', conditions = '[{"field":"event_name","op":"eq","value":"openat"},{"field":"comm","op":"in","value":["apt","apt-get","dpkg","dpkg-deb","yum","dnf","rpm"]},{"field":"filename","op":"starts_with","value":"/etc/"}]'::jsonb, severity_override = 0, tags = ARRAY(SELECT jsonb_array_elements_text('["package-manager","false-positive"]'::jsonb)), updated_at = NOW() WHERE built_in = true AND name = 'Downgrade package manager /etc reads';
UPDATE trace_detection_rules SET name = 'Downgrade monitoring agent /proc reads', description = 'Monitoring agents (WAFio, node_exporter, prometheus, telegraf) read /proc/* for metrics collection. Expected behavior.', action = 'downgrade', conditions = '[{"field":"event_name","op":"eq","value":"openat"},{"field":"comm","op":"in","value":["node_exporter","prometheus","telegraf","datadog-agent","collectd","zabbix_agentd"]},{"field":"filename","op":"starts_with","value":"/proc/"}]'::jsonb, severity_override = 0, tags = ARRAY(SELECT jsonb_array_elements_text('["monitoring","false-positive"]'::jsonb)), updated_at = NOW() WHERE built_in = true AND name = 'Downgrade monitoring agent /proc reads';
UPDATE trace_detection_rules SET name = 'Escalate interpreter /etc/shadow read', description = 'A shell or interpreter (bash, python, perl, ruby) reading /etc/shadow indicates potential credential harvesting — web shell or post-exploitation.', action = 'escalate', conditions = '[{"field":"event_name","op":"eq","value":"openat"},{"field":"comm","op":"in","value":["bash","sh","dash","zsh","python","python3","perl","ruby","php","lua"]},{"field":"filename","op":"contains","value":"/etc/shadow"}]'::jsonb, severity_override = 4, tags = ARRAY(SELECT jsonb_array_elements_text('["credential-access","web-shell","high-signal"]'::jsonb)), updated_at = NOW() WHERE built_in = true AND name = 'Escalate interpreter /etc/shadow read';
UPDATE trace_detection_rules SET name = 'Escalate AF_RXRPC socket creation (Dirty Frag / CVE-2026-43284)', description = 'AF_RXRPC (family=33) socket creation has no legitimate production use and is the entry point for the xfrm/RxRPC page cache write exploit (Dirty Frag). Any process creating this socket type should be investigated immediately.', action = 'escalate', conditions = '[{"field":"event_name","op":"eq","value":"socket"},{"field":"addr_family","op":"eq","value":33}]'::jsonb, severity_override = 4, tags = ARRAY(SELECT jsonb_array_elements_text('["lpe","dirty-frag","exploit","high-signal","cve-2026-43284"]'::jsonb)), updated_at = NOW() WHERE built_in = true AND name = 'Tag AF_RXRPC socket creation';
UPDATE trace_detection_rules SET name = 'Escalate IPPROTO_ESP raw socket creation (Dirty Frag / CVE-2026-43500)', description = 'Creating a raw IPPROTO_ESP (protocol=50) socket is the entry point for the xfrm-ESP Dirty Frag exploit. Legitimate ESP users (VPN daemons) run as root — this rule flags all ESP raw socket creation as a critical exploit indicator.', action = 'escalate', conditions = '[{"field":"event_name","op":"eq","value":"socket"},{"field":"flags","op":"eq","value":50}]'::jsonb, severity_override = 4, tags = ARRAY(SELECT jsonb_array_elements_text('["lpe","dirty-frag","exploit","high-signal","cve-2026-43500"]'::jsonb)), updated_at = NOW() WHERE built_in = true AND name = 'Tag raw ESP socket creation';
UPDATE trace_detection_rules SET name = 'Suppress Docker container init setuid', description = 'Container runtimes (runc, containerd-shim) call setuid(0) during container init. This is normal and not an attack.', action = 'suppress', tags = array_replace(tags, 'credential-change', 'false-positive'), updated_at = NOW() WHERE built_in = true AND name = 'Tag container runtime setuid';
UPDATE trace_detection_rules SET name = 'Suppress Docker container init setgid', description = 'Container runtimes call setgid(0) during container init. Normal behavior.', action = 'suppress', tags = array_replace(tags, 'credential-change', 'false-positive'), updated_at = NOW() WHERE built_in = true AND name = 'Tag container runtime setgid';
UPDATE trace_detection_rules SET name = 'Suppress self-setuid if comm is runc variant', description = 'Processes whose comm starts with ''runc:'' (e.g. runc:[2:INIT]) calling setuid are container init.', action = 'suppress', tags = array_replace(tags, 'credential-change', 'false-positive'), updated_at = NOW() WHERE built_in = true AND name = 'Tag runc credential change';
UPDATE trace_detection_rules SET name = 'Suppress postgres internal setuid/setgid', description = 'PostgreSQL drops privileges to the postgres user on startup. Normal behavior.', action = 'suppress', tags = array_replace(tags, 'credential-change', 'false-positive'), updated_at = NOW() WHERE built_in = true AND name = 'Tag postgres credential change';
UPDATE trace_detection_rules SET name = 'Suppress sshd setuid during normal auth', description = 'sshd drops to user privileges after auth by calling setuid. This is normal SSH server behavior. Covers privilege-separated sshd-session/sshd-auth (OpenSSH ≥9.x).', action = 'suppress', tags = array_replace(tags, 'credential-change', 'false-positive'), updated_at = NOW() WHERE built_in = true AND name = 'Tag sshd credential change';
